<?php
if(!defined('ABSPATH'))exit;
function sscwp_seed(){static $seed=null;if($seed===null)$seed=json_decode(file_get_contents(get_theme_file_path('seed/site.json')),true);return $seed;}
function sscwp_catalog_data(){return sscwp_seed()['catalog'];}
add_action('init',function(){
 foreach(['ssc_product'=>['Produkter','Produkt','produkter'],'ssc_customer'=>['Kundberättelser','Kundberättelse','kunder'],'ssc_news'=>['Nyheter','Nyhet','nyheter']] as $type=>$l)if(!post_type_exists($type))register_post_type($type,['labels'=>['name'=>$l[0],'singular_name'=>$l[1]],'public'=>true,'show_in_rest'=>true,'has_archive'=>false,'rewrite'=>['slug'=>$l[2],'with_front'=>false],'supports'=>['title','editor','excerpt','thumbnail','custom-fields','revisions'],'menu_icon'=>$type==='ssc_product'?'dashicons-products':'dashicons-admin-post']);
 if(!taxonomy_exists('ssc_category'))register_taxonomy('ssc_category','ssc_product',['label'=>'Produktkategorier','public'=>true,'show_in_rest'=>true,'hierarchical'=>true,'rewrite'=>['slug'=>'produktkategorier','with_front'=>false]]);
 foreach(['page','ssc_product','ssc_news','ssc_customer']as $type)foreach(['_ssc_description','_ssc_noindex']as $key)register_post_meta($type,$key,['single'=>true,'type'=>'string','show_in_rest'=>true,'auth_callback'=>function($allowed,$key,$id){return current_user_can('edit_post',$id);},'default'=>'']);
 $string=['type'=>'string'];$number=['type'=>['number','null']];
 $application=['type'=>'object','properties'=>['category'=>$string,'vehicle'=>$string,'fuels'=>['type'=>'array','items'=>$string],'minKw'=>$number,'maxKw'=>$number,'voltage'=>['type'=>['string','null']],'description'=>$string]];
 $variant=['type'=>'object','properties'=>['name'=>$string,'model'=>$string,'series'=>$string,'heatSource'=>['type'=>['string','null']],'articleNumber'=>['type'=>['string','null']],'applications'=>['type'=>'array','items'=>$application]]];
 $schemas=['brand'=>$string,'desc'=>$string,'variants'=>['type'=>'array','items'=>$variant],'benefits'=>['type'=>'array','items'=>['type'=>'array','items'=>$string]],'specs'=>['type'=>'array','items'=>['type'=>'array','items'=>$string]],'downloads'=>['type'=>'array','items'=>['type'=>'array','items'=>$string]],'addons'=>['type'=>'array','items'=>['type'=>'integer']]];
 foreach($schemas as $name=>$schema)register_post_meta('ssc_product','sscwp_'.$name,['single'=>true,'type'=>$schema['type'],'show_in_rest'=>['schema'=>$schema],'auth_callback'=>function($allowed,$key,$id){return current_user_can('edit_post',$id);},'default'=>$schema['type']==='string'?'':[]]);
});
function sscwp_product_data($id=0){$id=$id?:get_the_ID();$p=['id'=>$id,'name'=>get_the_title($id),'image'=>get_the_post_thumbnail_url($id,'full')?:''];foreach(['brand','desc','variants','benefits','specs','downloads','addons']as $key)$p[$key]=get_post_meta($id,'sscwp_'.$key,true)?: (in_array($key,['brand','desc'],true)?'':[]);return $p;}
function sscwp_labels($kind){$out=[];foreach(sscwp_catalog_data()[$kind]as $v)$out[$v[0]]=$v[1];return $out;}
function sscwp_category_name($id){foreach(sscwp_catalog_data()['categories']as $c)if($c['id']===$id)return $c['name'];return '';}
function sscwp_product_tags($p){$used=['vehicles'=>[],'fuels'=>[]];foreach($p['variants']as $v)foreach($v['applications']??[]as $a){$used['vehicles'][]=$a['vehicle'];$used['fuels']=array_merge($used['fuels'],$a['fuels']??[]);}$out='<div class="tag-list">';foreach($used as $kind=>$ids)foreach(sscwp_labels($kind)as $id=>$label)if(in_array($id,$ids,true))$out.='<span class="tag">'.esc_html($label).'</span>';return $out.'</div>';}
function sscwp_folder($title,$docs){$out='<details class="document-folder" open><summary>'.sscwp_icon('file').'<span>'.esc_html($title).'</span>'.sscwp_icon('chevron').'</summary><div class="document-folder-body">';foreach($docs as $d)$out.='<a class="download-link" href="'.esc_url(sscwp_url($d[1]??'')).'" target="_blank" rel="noopener"><span>'.esc_html($d[0]).'<small>Öppnas i ny flik</small></span>'.sscwp_arrow().'</a>';if(!$docs)$out.='<div class="document-empty" aria-label="Inga dokument tillagda"></div>';return $out.'</div></details>';}
function sscwp_power($a){$min=$a['minKw']??null;$max=$a['maxKw']??null;if($min===null)return '';return $max===null?'Från '.$min.' kW':($min==$max?$min:$min.'–'.$max).' kW';}
function sscwp_product_section($section){
 if(get_post_type()!=='ssc_product')return '<p>Denna sektion visar data på en produktsida.</p>';$p=sscwp_product_data();$out='';
 if($section==='hero')return '<section class="product-hero"><div class="product-visual">'.sscwp_image($p['image'],$p['name'],'',false).'</div><div class="product-summary"><h1>'.esc_html($p['name']).'</h1><p>'.esc_html($p['desc']).'</p>'.sscwp_product_tags($p).'</div></section>';
 if($section==='benefits'){$out='<section class="detail-benefits"><h2>Viktigaste egenskaper</h2><div class="detail-benefit-grid">';foreach($p['benefits']as $i=>$b)$out.='<div class="benefit">'.sscwp_icon(['shield','bolt','tool','leaf'][$i%4]).'<div><h3>'.esc_html($b[0]).'</h3><p>'.esc_html($b[1]??'').'</p></div></div>';return $out.'</div></section>';}
 if($section==='technical'){$out='<section><h2>Teknisk information</h2><table class="spec-table"><thead><tr><th scope="col">Egenskap</th><th scope="col">Specifikation</th></tr></thead><tbody>';foreach($p['specs']as $s)$out.='<tr><th scope="row">'.esc_html($s[0]).'</th><td>'.esc_html($s[1]??'').'</td></tr>';return $out.'</tbody></table></section>';}
 if($section==='downloads')return '<section><h2>Downloads</h2><div class="document-folders">'.sscwp_folder('Produktblad',array_values(array_filter($p['downloads'],fn($d)=>($d[2]??'')!=='manual'))).sscwp_folder('Manualer',array_values(array_filter($p['downloads'],fn($d)=>($d[2]??'')==='manual'))).'</div></section>';
 if($section==='models'){if($p['brand']!=='SSC Climate Group'||!$p['variants'])return '';$out='<section class="product-models"><h2>Modeller och utföranden</h2><div class="product-model-list">';foreach($p['variants']as $v){$label=($v['model']??'')?:($v['series']??'');if(($v['series']??'')==='VIL EX')$label.=' · EX';$out.='<details class="product-model"><summary><span>'.esc_html($label).'</span>'.sscwp_icon('chevron').'</summary><div class="product-model-body">';if(!empty($v['heatSource']))$out.='<p><strong>Värmekälla:</strong> '.esc_html($v['heatSource']).'</p>';if(!empty($v['articleNumber']))$out.='<p><strong>Produktnummer:</strong> '.esc_html($v['articleNumber']).'</p>';$out.='<div class="model-table-scroll" role="region" tabindex="0" aria-label="Utföranden för '.esc_attr($label).'"><table class="spec-table model-table"><thead><tr><th>Användning</th><th>Typ</th><th>Energikälla</th><th>Värmeeffekt</th><th>Spänning</th></tr></thead><tbody>';$vehicles=sscwp_labels('vehicles');$fuels=sscwp_labels('fuels');foreach($v['applications']??[]as $a)$out.='<tr><td>'.esc_html(sscwp_category_name($a['category'])).'</td><td>'.esc_html($vehicles[$a['vehicle']]??'').'</td><td>'.esc_html(implode(' · ',array_map(fn($id)=>$fuels[$id]??$id,$a['fuels']??[]))).'</td><td>'.esc_html(sscwp_power($a)).'</td><td>'.esc_html($a['voltage']??'').'</td></tr>';$out.='</tbody></table></div></div></details>';}return $out.'</div></section>';}
 if($section==='addons'){$out='<section class="detail-addons"><h2>Kompatibla tillval</h2><div class="detail-addon-grid">';foreach($p['addons']as $id)if(get_post_status($id)==='publish')$out.='<a class="detail-addon-card" href="'.esc_url(get_permalink($id)).'"><div class="detail-addon-image">'.get_the_post_thumbnail($id,'medium').'</div><h3>'.esc_html(get_the_title($id)).'</h3>'.sscwp_arrow().'</a>';return $out.'</div></section>';}
 return '';
}
function sscwp_matches($p,$category,$vehicles=[],$fuels=[]){foreach($p['variants']as $v)foreach($v['applications']??[]as $a)if((!$category||$category===($a['category']??''))&&(!$vehicles||in_array($a['vehicle']??'',$vehicles,true))&&(!$fuels||array_intersect($fuels,$a['fuels']??[])))return true;return false;}
function sscwp_catalog($attrs){
 $category=$attrs['category']??'';if(!$category&&is_tax('ssc_category'))$category=get_queried_object()->slug;
 $cat=null;foreach(sscwp_catalog_data()['categories']as $c)if($c['id']===$category)$cat=$c;
 if($category&&!$cat)return '<p>Produktkategorin finns inte.</p>';
 $products=array_map(fn($p)=>sscwp_product_data($p->ID),get_posts(['post_type'=>'ssc_product','numberposts'=>-1,'orderby'=>'menu_order title','order'=>'ASC','post_status'=>'publish']));
 $selectedVehicles=array_values(array_filter(array_map('sanitize_key',(array)($_GET['vehicle']??[]))));$selectedFuels=array_values(array_filter(array_map('sanitize_key',(array)($_GET['fuel']??[]))));
 $available=['vehicles'=>[],'fuels'=>[]];foreach($products as $p)foreach($p['variants']as $v)foreach($v['applications']??[]as $a)if(!$category||$category===$a['category']){$available['vehicles'][]=$a['vehicle'];$available['fuels']=array_merge($available['fuels'],$a['fuels']??[]);}
 $title=$cat['name']??'Alla produkter';$out='<div class="wrap simple-catalog"><form method="get" class="ssc-catalog-form"><div class="catalog-overview"><section class="simple-category-heading">';if($cat)$out.='<div class="simple-category-image">'.sscwp_image($cat['image'],$title,'',false).'</div>';$out.='<div><h1>'.esc_html($title).'</h1>'.($cat?'<p>'.esc_html($cat['desc']).'</p>':'').'</div></section><section class="filters simple-filters" aria-label="Produktfilter"><div class="filter-groups">';
 foreach(['vehicles'=>['vehicle','Typ',$selectedVehicles],'fuels'=>['fuel','Energikälla',$selectedFuels]]as $kind=>$group){$options=array_intersect_key(sscwp_labels($kind),array_flip($available[$kind]));if(!$options)continue;$out.='<fieldset><legend>'.esc_html($group[1]).'</legend><div class="filter-options">';foreach($options as $id=>$label)$out.='<label class="filter-option"><input type="checkbox" name="'.$group[0].'[]" value="'.esc_attr($id).'" '.checked(in_array($id,$group[2],true),true,false).'><span>'.esc_html($label).'</span></label>';$out.='</div></fieldset>';}
 $out.='</div><div class="ssc-filter-submit"><button class="btn" type="submit">Visa produkter '.sscwp_arrow().'</button><a href="'.esc_url(sscwp_url($category?'/produktkategorier/'.$category:'/alla-produkter')).'">Nollställ filter</a></div></section></div></form>';
 $found=array_values(array_filter($products,fn($p)=>sscwp_matches($p,$category,$selectedVehicles,$selectedFuels)));
 $out.='<section class="simple-products"><div class="simple-products-heading"><h2>Produkter</h2><p class="result-count">'.count($found).' produkter</p></div><div class="product-grid">';foreach($found as $p)$out.='<a class="product-card simple-product-card" href="'.esc_url(get_permalink($p['id'])).'" aria-label="Visa '.esc_attr($p['name']).'"><div class="product-img">'.sscwp_image($p['image'],$p['name']).'</div><div class="product-info"><h3>'.esc_html($p['name']).'</h3><p>'.esc_html($p['desc']).'</p><span class="simple-product-arrow">'.sscwp_arrow().'</span></div></a>';
 if(!$found)$out.='<p>Ingen matchande produkt. Prova en annan kombination.</p>';return $out.'</div></section></div>';
}
add_action('rest_after_insert_ssc_product',function($post){$ids=[];foreach(sscwp_product_data($post->ID)['variants']as $v)foreach($v['applications']??[]as $a)if(!empty($a['category']))$ids[]=$a['category'];wp_set_object_terms($post->ID,array_values(array_unique($ids)),'ssc_category');},10,1);
